      "path": "package.json",
      "content": "{\n  \"name\": \"huaweicloud-devkit\",\n  \"mcpName\": \"io.github.huaweicloud/huaweicloud-devkit\",\n  \"version\": \"1.1.12\",\n  \"kooCliVersion\": \"7.3.12\",\n  \"description\": \"Agent toolkit that helps coding agents use Huawei Cloud Skills, KooCLI, APIs, SDKs, and future MCP capabilities safely and accurately.\",\n  \"type\": \"module\",\n  \"files\": [\n    \"cordis.patch.yml\",\n    \"bin\",\n    \".agents\",\n    \"rules\",\n    \"plugins/huaweicloud-core\",\n    \"integrations/hermes\",\n    \"integrations/opencode\",\n    \"integrations/dsh\",\n    \"integrations/workbuddy\",\n    \"integrations/atomcode\"\n  ],\n  \"bin\": {\n    \"huaweicloud-devkit\": \"./bin/setup.cjs\",\n    \"huaweicloud-devkit-mcp\": \"./plugins/huaweicloud-core/src/mcp-server.mjs\"\n  },\n  \"repository\": {\n    \"type\": \"git\",\n    \"url\": \"https://github.com/huaweicloud/huaweicloud-devkit.git\"\n  },\n  \"dsh\": {\n    \"bundle\": {\n      \"patch\": \"./cordis.patch.yml\"\n    }\n  },\n  \"scripts\": {\n    \"test\": \"node --experimental-test-module-mocks --test \\\"test/*.test.mjs\\\"\",\n    \"format\": \"prettier --write .\",\n    \"format:check\": \"prettier --check .\",\n    \"lint:md\": \"markdownlint-cli2 \\\"**/*.md\\\" \\\"#node_modules\\\" \\\"#.git\\\" \\\"#test/**\\\" \\\"#docs/**\\\" \\\"#.superpowers/**\\\"\",\n    \"lint:js\": \"eslint .\",\n    \"lint\": \"npm run lint:md && npm run lint:js\",\n    \"validate\": \"node ./scripts/validate-package.mjs && node ./scripts/sync-readme-badge.mjs\",\n    \"badge:sync\": \"node ./scripts/sync-readme-badge.mjs --write\",\n    \"pack:verify\": \"node ./scripts/pack-verify.mjs\",\n    \"postinstall\": \"node ./bin/dsh-postinstall.cjs\"\n  },\n  \"dependencies\": {\n    \"undici\": \"^8.11.2\"\n  },\n  \"devDependencies\": {\n    \"@eslint/js\": \"^10.0.1\",\n    \"eslint\": \"^10.8.1\",\n    \"eslint-config-prettier\": \"^10.1.8\",\n    \"eslint-plugin-import-x\": \"^4.17.1\",\n    \"eslint-plugin-n\": \"^18.3.0\",\n    \"eslint-plugin-unicorn\": \"^73.0.0\",\n    \"globals\": \"^17.11.0\",\n    \"markdownlint-cli2\": \"^0.23.2\",\n    \"prettier\": \"^3.9.6\"\n  },\n  \"overrides\": {\n    \"smol-toml\": \"^1.9.0\",\n    \"brace-expansion\": \"5.0.12\",\n    \"katex\": \"^0.19.0\"\n  },\n  \"keywords\": [\n    \"huaweicloud\",\n    \"huawei-cloud\",\n    \"agent\",\n    \"codex\",\n    \"opencode\",\n    \"codearts\",\n    \"codearts-work\",\n    \"officeace\",\n    \"office-claw\",\n    \"workbuddy\",\n    \"atomcode\",\n    \"dsh\",\n    \"deepseek-harness\",\n    \"mcp\",\n    \"koocli\",\n    \"hcloud\"\n  ],\n  \"license\": \"Apache-2.0\",\n  \"engines\": {\n    \"node\": \">=22\"\n  }\n}\n"
