      "path": "plugins/huaweicloud-core/src/tools.mjs",
      "content": "import { readFileSync, readdirSync, existsSync, writeFileSync, rmSync, mkdirSync } from 'node:fs';\nimport { join, dirname, basename } from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { homedir, tmpdir } from 'node:os';\nimport { spawnSync, execFile } from 'node:child_process';\nimport { promisify } from 'node:util';\nimport { createHmac, createHash } from 'node:crypto';\n\nimport { evaluateArtifacts, evaluateCommandRisk, evaluateDeployPlan } from './risk-rule-engine.mjs';\nimport { classifyTextCommand, redactSecrets } from './safety-policy.mjs';\nimport { planHcloudCommand, runHcloud, consumeApprovalToken, inspectApprovalToken, hashArgs } from './hcloud-cli.mjs';\nimport { checkAccountType } from './account-type.mjs';\nimport { searchMarketplace } from './search-market.mjs';\nimport { getServiceIcon } from './icon-library.mjs';\nimport { detectFramework } from './detect-framework.mjs';\nimport {\n  execWithSession,\n  execOneShot,\n  closeSession,\n  uploadFileWithSession,\n  uploadProjectWithSession,\n  deployNginx,\n  deployCheck,\n  exposeTunnel,\n  renewTunnel,\n  installKeepaliveWatchdog,\n  getCurrentWorkspaceId,\n  setWorkspaceId,\n} from './sandbox/session-manager.mjs';\nimport {\n  hdkitCheckUser,\n  hdkitSignAgreement,\n  hdkitConnect,\n  hdkitCredentials,\n  hdkitVoucherStatus,\n  hdkitVoucherClaim,\n  hdkitCompetitionVoucherClaim,\n  hdkitGenerateUserHash,\n} from './sandbox/hdkitservice-api.mjs';\nimport { getCredentials } from './sandbox/hwlink-api.mjs';\nimport { getAuthStatus, syncAuth } from './auth/service.mjs';\nimport { validateIamCredentials } from './auth/credential-validator.mjs';\nimport {\n  readGlobalCredentials,\n  writeGlobalCredentials,\n  writeObsConfig as writeObsConfigFile,\n  setRuntimeCredentials,\n  clearRuntimeCredentials,\n  setConfiguredBySession,\n  backupGlobalCredentials,\n  writeLastSync,\n  readCodeArtsCredentials,\n  globalCredentialsPath,\n  parseStsExpiry,\n  resolveCredentialsWithRuntime,\n} from './auth/credentials.mjs';\nimport { trackToolInvoke, trackSkillRetrieve, clearUserHash } from './telemetry/telemetry.mjs';\nimport { fetchWithProxy } from './proxy/proxy-agent.mjs';\nimport { fingerprint, runHcloudConfigure, runHcloudProfileDelete, resolveManagedProfile } from './auth/reconcile.mjs';\nimport {\n  getCachedUpdateInfo,\n  getUpdateDistTags,\n  invalidateUpdateCache,\n  judgeUpdate,\n  determineTarget,\n  readInstalledVersion,\n  writeSkipState,\n  resolveSkipFilePath,\n  upgradePackage,\n} from './update-check.mjs';\nimport { hcloudProbeNextStep, hcloudProbeRaw, probeHcloud } from './hcloud-probe.mjs';\nimport { isUsableOfficeaceRoot, readOfficeaceRootMarker } from './officeace-paths.mjs';\n\nconst __dirname = dirname(fileURLToPath(import.meta.url));\nconst SKILLS_ROOT_DEV = join(__dirname, '..', 'skills');\nfunction opencodeSkillsDir() {\n  const home = homedir();\n  return join(home, '.config', 'opencode', 'skills');\n}\nfunction codeartsSkillsDir() {\n  const home = homedir();\n  return join(home, '.codeartsdoer', 'skills');\n}\nfunction codeartsWorkSkillsDir() {\n  const home = homedir();\n  return join(home, '.codeartswork', 'skills');\n}\nfunction workbuddySkillsDir() {\n  const home = homedir();\n  return join(home, '.workbuddy', 'skills');\n}\nfunction dshSkillsDir() {\n  const home = process.env.DSH_HOME || join(homedir(), '.dsh');\n  return join(home, 'skills');\n}\nfunction readOfficeaceRegistryInstallDir() {\n  if (process.platform !== 'win32') return null;\n  try {\n    const r = spawnSync('reg', ['query', 'HKCU\\\\SOFTWARE\\\\OfficeAce\\\\OfficeAce', '/v', 'InstallDir'], {\n      encoding: 'utf8',\n      windowsHide: true,\n      timeout: 5000,\n    });\n    if (r.status === 0) {\n      const m = r.stdout.match(/InstallDir\\s+REG_SZ\\s+(.+)/);\n      if (m) return m[1].trim();\n    }\n  } catch {}\n  return null;\n}\n\nfunction officeaceSkillsRoot() {\n  const configRoot = process.env.OFFICE_CLAW_CONFIG_ROOT;\n  // Same lenient probe as the installer (isUsableOfficeaceRoot) so env pointing\n  // at \"skills present but capabilities.json absent\" resolves identically at\n  // install and at runtime (#559 review).\n  if (configRoot && isUsableOfficeaceRoot(configRoot)) return join(configRoot, 'skills');\n  // Same persisted root used by the installer keeps install-time and\n  // runtime skill discovery consistent (#559).\n  const markerRoot = readOfficeaceRootMarker();\n  if (markerRoot) return join(markerRoot, 'skills');\n  const regDir = readOfficeaceRegistryInstallDir();\n  if (regDir) {\n    const dir = join(regDir, '.office-claw', 'skills');\n    if (existsSync(dir)) return dir;\n  }\n  if (process.platform === 'win32') {\n    const bases = [process.env.ProgramFiles, 'C:\\\\Program Files', 'D:\\\\Program Files'];\n    if (process.env.LOCALAPPDATA) bases.push(join(process.env.LOCALAPPDATA, 'Programs'));\n    for (const base of bases) {\n      if (!base) continue;\n      const dir = join(base, 'OfficeAce', '.office-claw', 'skills');\n      if (existsSync(dir)) return dir;\n    }\n  }\n  return null;\n}\n\nfunction hermesSkillsDir() {\n  if (process.env.HERMES_HOME) return join(process.env.HERMES_HOME, 'skills');\n  // Hermes on Windows stores under LOCALAPPDATA, not ~/.hermes\n  if (process.platform === 'win32' && process.env.LOCALAPPDATA) {\n    return join(process.env.LOCALAPPDATA, 'hermes', 'skills');\n  }\n  const home = homedir();\n  return join(home, '.hermes', 'skills');\n}\n\nfunction atomcodeSkillsDir() {\n  const home = process.env.ATOMCODE_HOME || homedir();\n  return join(home, '.atomcode', 'skills');\n}\n\nfunction codexDesktopSkillsDir() {\n  return join(homedir(), '.agents', 'skills');\n}\n\nexport function listSkillDirs(root) {\n  if (!existsSync(root)) return [];\n  try {\n    return readdirSync(root, { withFileTypes: true })\n      .filter((d) => (d.isDirectory() || d.isSymbolicLink()) && existsSync(join(root, d.name, 'SKILL.md')))\n      .map((d) => d.name);\n  } catch {\n    return [];\n  }\n}\n\nexport function findSkillsRoot(candidates) {\n  for (const dir of candidates) {\n    if (listSkillDirs(dir).length > 0) return dir;\n  }\n  return null;\n}\n\nfunction resolveSkillsRoot() {\n  return (\n    findSkillsRoot([\n      SKILLS_ROOT_DEV,\n      dshSkillsDir(),\n      codeartsSkillsDir(),\n      codeartsWorkSkillsDir(),\n      opencodeSkillsDir(),\n      workbuddySkillsDir(),\n      officeaceSkillsRoot(),\n      hermesSkillsDir(),\n      atomcodeSkillsDir(),\n      codexDesktopSkillsDir(),\n    ]) || SKILLS_ROOT_DEV\n  );\n}\nconst SKILLS_ROOT = resolveSkillsRoot();\n\nexport const TOOL_DEFINITIONS = [\n  {\n    name: 'huaweicloud_check_cli',\n    description:\n      'Check whether Huawei Cloud KooCLI hcloud is installed and whether its version matches the plugin paired version. Returns redacted output.',\n    inputSchema: {\n      type: 'object',\n      properties: {},\n    },\n  },\n  {\n    name: 'huaweicloud_plan_cli_command',\n    description: 'Classify and plan a Huawei Cloud hcloud command without executing it.',\n    inputSchema: {\n      type: 'object',\n      required: ['args'],\n      properties: {\n        args: {\n          type: 'array',\n          items: { type: 'string' },\n          description: 'hcloud arguments, excluding the hcloud executable.',\n        },\n        allowWrites: {\n          type: 'boolean',\n          description: 'Only true after explicit user approval for this exact operation.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_run_readonly_command',\n    description: 'Run a read-only hcloud command through the toolkit safety policy and redact output.',\n    inputSchema: {\n      type: 'object',\n      required: ['args'],\n      properties: {\n        args: {\n          type: 'array',\n          items: { type: 'string' },\n        },\n        timeoutMs: {\n          type: 'number',\n          description: 'Optional timeout in milliseconds. Defaults to 60000.',\n        },\n        maxRetries: {\n          type: 'number',\n          description: 'Optional retry count for transient network errors. Defaults to 1.',\n        },\n        cwd: {\n          type: 'string',\n          description: 'Optional working directory for the hcloud process.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_list_operations',\n    description:\n      'List KooCLI operations for a Huawei Cloud service by running local/read-only hcloud <Service> --help.',\n    inputSchema: {\n      type: 'object',\n      required: ['service'],\n      properties: {\n        service: {\n          type: 'string',\n          description: 'KooCLI service name, such as ECS, VPC, IMS, OBS, RDS, or CDN.',\n        },\n        timeoutMs: {\n          type: 'number',\n          description: 'Optional timeout in milliseconds. Defaults to 60000.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_run_approved_command',\n    description:\n      'Run a write-capable hcloud command only after the exact command has been shown and explicitly approved by the user.',\n    inputSchema: {\n      type: 'object',\n      required: ['args', 'approvalToken', 'approvedByUser'],\n      properties: {\n        args: {\n          type: 'array',\n          items: { type: 'string' },\n          description: 'hcloud arguments, excluding the hcloud executable.',\n        },\n        approvalToken: {\n          type: 'string',\n          description: 'The approvalToken returned by huaweicloud_plan_cli_command.',\n        },\n        approvedByUser: {\n          type: 'boolean',\n          description: 'Must be true only after the user explicitly approves this exact command.',\n        },\n        timeoutMs: {\n          type: 'number',\n          description: 'Optional timeout in milliseconds. Defaults to 60000.',\n        },\n        maxRetries: {\n          type: 'number',\n          description: 'Optional retry count for transient network errors. Defaults to 1.',\n        },\n        cwd: {\n          type: 'string',\n          description: 'Optional working directory for the hcloud process.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_show_profile_redacted',\n    description: 'Inspect a KooCLI profile through hcloud configure show and return only redacted output.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        profile: {\n          type: 'string',\n          description: 'Optional KooCLI profile name.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_hook_check_command',\n    description: 'Check a planned shell or hcloud command against Huawei Cloud hook risk rules without executing it.',\n    inputSchema: {\n      type: 'object',\n      required: ['command'],\n      properties: {\n        command: { type: 'string', description: 'The exact command text to inspect.' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_hook_check_artifacts',\n    description: 'Check generated code, IaC, policy, or config artifacts against Huawei Cloud hook risk rules.',\n    inputSchema: {\n      type: 'object',\n      required: ['artifacts'],\n      properties: {\n        artifacts: {\n          type: 'array',\n          items: {\n            type: 'object',\n            required: ['path', 'content'],\n            properties: {\n              path: { type: 'string' },\n              content: { type: 'string' },\n            },\n          },\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_hook_check_deploy_plan',\n    description:\n      'Check a structured or textual deployment plan for Huawei Cloud sandbox, exposure, IAM, and cost risks.',\n    inputSchema: {\n      type: 'object',\n      required: ['plan'],\n      properties: {\n        plan: {\n          description: 'Deployment plan as an object, array, or string.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_service_catalog',\n    description: 'Return the recommended capability sources for Huawei Cloud agent tasks.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        intent: {\n          type: 'string',\n          description: 'Developer intent to route, such as deploy app, use API, debug error, or inspect resources.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_explain_error',\n    description: 'Explain a Huawei Cloud CLI, API, SDK, or agent workflow error and suggest next diagnostic steps.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        service: { type: 'string' },\n        errorCode: { type: 'string' },\n        message: { type: 'string' },\n        requestId: { type: 'string' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_search_docs',\n    description:\n      'Search across Huawei Cloud SKILL.md files and local documentation. Returns top 10 relevant results with source, name, snippet, and relevance score. Use when the agent needs to discover which skill covers a topic, or when uncertain about API parameters, quotas, or limitations.',\n    inputSchema: {\n      type: 'object',\n      required: ['query'],\n      properties: {\n        query: { type: 'string', description: 'Search query across skill descriptions and documentation.' },\n        topic: {\n          type: 'string',\n          description: 'Optional filter: all | ecs | obs | vpc | iam | rds | cce | modelarts | dew. Defaults to all.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_retrieve_skill',\n    description:\n      'Retrieve a full SKILL.md by skill name. Returns the complete skill content plus list of reference files. Use when the agent has identified which skill to load and needs the full procedure.',\n    inputSchema: {\n      type: 'object',\n      required: ['name'],\n      properties: {\n        name: { type: 'string', description: 'Skill name, e.g., huaweicloud-core, huawei-ecs, huawei-obs.' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_list_regions',\n    description:\n      'List available Huawei Cloud regions. Returns region IDs, display names, and endpoints. Use when the agent needs to discover available regions before creating resources.',\n    inputSchema: {\n      type: 'object',\n      properties: {},\n    },\n  },\n  {\n    name: 'huaweicloud_check_account_type',\n    description:\n      'Check whether the current credentials belong to the primary account or an IAM sub-user. Runs STS GetCallerIdentity + IAM KeystoneListAuthDomains (both read-only, no identity-policy permission required) and applies the validated rule: username == domainName -> primary account, otherwise IAM sub-user. Use before sandbox deployment (primary-account prechecks), account confirmation, or any task that needs to know who the current AK/SK belongs to. Returns isPrimaryAccount, applicable, domainId, domainName, userId, username, principalUrn, and an evidence string. Agency-session credentials are detected and reported as applicable:false.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        region: {\n          type: 'string',\n          description:\n            'Optional region ID for the region-level GetCallerIdentity endpoint (e.g., cn-north-4). Defaults to the configured cli-region.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_get_regional_availability',\n    description:\n      'Check if a specific Huawei Cloud service is available in a target region. Use before creating resources to prevent failures from regional unavailability.',\n    inputSchema: {\n      type: 'object',\n      required: ['service', 'region'],\n      properties: {\n        service: {\n          type: 'string',\n          description: 'Service name: ecs, obs, rds, gaussdb, cce, modelarts, functiongraph, etc.',\n        },\n        region: { type: 'string', description: 'Region ID: cn-south-1, cn-north-4, ap-southeast-3, etc.' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_search_marketplace',\n    description:\n      'Search the Huawei Cloud agent skill marketplace for available skills. Returns scored results with names, categories, and descriptions. Use when built-in skills are insufficient or the user asks what skills exist.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        query: { type: 'string', description: 'Search query across skill name, description, triggers, and service.' },\n        category: {\n          type: 'string',\n          description: 'Optional category filter: computing, storage, network, security, devtools, monitoring, etc.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_get_service_icon',\n    description:\n      'Find the official Huawei Cloud service logo from the Huawei Cloud Icons library (open.huaweicloud.com/openplatform/icons.html). Returns top 5 matches with CDN logo URLs, local paths, category, aliases, and product page links. Provide service (e.g. ecs, obs, modelarts, 对象存储) or category (e.g. 计算, 存储, 人工智能) to browse. Use when generating PPT, architecture diagrams (draw.io), or frontend pages that need official Huawei Cloud service logos.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        service: {\n          type: 'string',\n          description:\n            'Service name, alias, or Chinese name, e.g. ecs, obs, modelarts, 对象存储, 虚拟私有云. Omit to browse by category only.',\n        },\n        category: {\n          type: 'string',\n          description: 'Optional category filter, e.g. 计算, 存储, 网络, 人工智能, 数据库, 安全, 企业应用.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_detect_framework',\n    description:\n      'Scan a local project directory to identify the web framework (React/Vue/Angular/Next.js/Nuxt/VitePress/Docusaurus/Hugo/Hexo/Taro/uni-app), package manager, and monorepo tool. Returns framework type, build commands, output directory, and port. Use before deploying a web application to determine the correct build pipeline.',\n    inputSchema: {\n      type: 'object',\n      required: ['projectPath'],\n      properties: {\n        projectPath: { type: 'string', description: 'Absolute path to the local project directory to scan.' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_setup_obs_config',\n    description:\n      'Synchronize KooCLI credentials to OBS config (~/.obsutilconfig). KooCLI and OBS use separate credential stores — hcloud commands work fine but OBS commands fail with \"Please set ak, sk\" unless this sync is done. Run this once to enable OBS operations; re-run after changing hcloud credentials.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        profile: { type: 'string', description: 'Optional KooCLI profile name. Uses the active profile by default.' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_auth_status',\n    description:\n      'Check unified Huawei Cloud authentication status across the global credential vault, OBS, KooCLI, and all supported agent MCP registrations. Returns only redacted/status information, never credentials.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        target: {\n          type: 'string',\n          description:\n            'Agent target to check: opencode, codex, codex-desktop, codearts, codearts-work, workbuddy, dsh, officeace, hermes, openclaw, atomcode, or all (default).',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_auth_sync',\n    description:\n      'Synchronize credentials from the global Huawei Cloud credential vault to OBS and report agent registration status. Does not write secrets into any agent config.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        target: {\n          type: 'string',\n          description:\n            'Agent target to report after sync: opencode, codex, codex-desktop, codearts, codearts-work, workbuddy, dsh, officeace, hermes, or all (default).',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_auth_init',\n    description:\n      'Set or clear runtime Huawei Cloud credentials (AK/SK) for this MCP session. Runtime credentials take highest priority over environment variables and config files for all subsequent API calls. Use when switching accounts within the same Agent session — call with AK/SK to switch, or with clear=true to fall back to env/file credentials.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        ak: { type: 'string', description: 'Huawei Cloud Access Key (required unless clear=true)' },\n        sk: { type: 'string', description: 'Huawei Cloud Secret Key (required unless clear=true)' },\n        region: { type: 'string', description: 'Default region (optional)' },\n        clear: { type: 'boolean', description: 'Set to true to clear runtime credentials and revert to env/file' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_auth_switch',\n    description:\n      'Switch Huawei Cloud credentials within the current session. action=temporary keeps AK/SK in memory only (restart loses them; hcloud commands are unaffected and an A+C warning will be raised). action=persist writes S1 (single source of truth) with configuredBySession flag and propagates to S2 (KooCLI current profile) and S3 (OBS). action=clear resets runtime credentials. mode=import reads AK/SK from ~/.config/huaweicloud/creds-import.json then wipes it (SK never enters conversation). mode=memory passes AK/SK as tool arguments (SK is visible to model - prefer import). mode=mcp-config reads the injected mcp_settings environment.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        mode: { type: 'string', enum: ['import', 'memory', 'mcp-config'], description: 'Credential source channel' },\n        action: { type: 'string', enum: ['persist', 'temporary', 'clear'], description: 'Apply scope' },\n        ak: { type: 'string' },\n        sk: { type: 'string' },\n        securityToken: { type: 'string' },\n        region: { type: 'string' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_auth_confirm',\n    description:\n      'Confirm a pending credential reconciliation choice returned by auth_switch persist when S1 already holds a different account (R2). decision=s1 keeps S1 as source of truth and propagates it; decision=newImported propagates the newly imported account into S1 and mirrors.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        token: { type: 'string', description: 'confirmation token from the needs_confirmation response' },\n        decision: { type: 'string', enum: ['s1', 'newImported'] },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_exec_with_session',\n    description:\n      'Execute a command on a workspace terminal with session reuse (state persists across calls). Shell state (cd, env vars, aliases) carries over between calls. Use for interactive work and command sequences that need shared state. NOT for long-running commands (>30s) — prefer exec_one_shot for those.',\n    inputSchema: {\n      type: 'object',\n      required: ['command'],\n      properties: {\n        command: { type: 'string', description: 'The shell command to execute on the remote workspace' },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username for the remote terminal (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 120000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_exec_one_shot',\n    description:\n      'Execute a command on a workspace terminal with a fresh connection per call (no session state carries over). Each invocation opens a new WebSocket connection, executes one command, then disconnects. Use for long-running build/deploy/install commands (>30s) that do not need shell state persistence between calls. More stable than session-based execution for heavy workloads.',\n    inputSchema: {\n      type: 'object',\n      required: ['command'],\n      properties: {\n        command: { type: 'string', description: 'The shell command to execute on the remote workspace' },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username for the remote terminal (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 120000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_close_session',\n    description: 'Close the persistent terminal session for a workspace.',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_upload_file',\n    description:\n      'Upload a local file into the sandbox workspace. Base64-encodes the file, writes it in small chunks through the terminal session (the exec channel is fragile for large single commands), then decodes and verifies the md5 checksum. The remote parent directory is created automatically if absent. Use this instead of embedding large file content directly in a command. local_path must be readable from the machine running the DevKit MCP server — if the file lives elsewhere, copy it to the local temp directory first.',\n    inputSchema: {\n      type: 'object',\n      required: ['local_path', 'remote_path'],\n      properties: {\n        local_path: {\n          type: 'string',\n          description:\n            'Absolute path to the local file, readable from the machine running the DevKit MCP server (copy to the local temp dir first if not).',\n        },\n        remote_path: { type: 'string', description: 'Target path in the sandbox, e.g. /workspace/<repo>/index.html.' },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 60000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_upload_project',\n    description:\n      'Package a local project directory and upload it to a sandbox workspace via HTTP tunnel. Falls back to base64 chunking if tunnel fails. Creates a tar.gz archive, uploads it, and extracts it on the sandbox by default. local_dir must be readable from the machine running the DevKit MCP server — if the project lives elsewhere, copy it to the local temp directory first.',\n    inputSchema: {\n      type: 'object',\n      required: ['local_dir'],\n      properties: {\n        local_dir: {\n          type: 'string',\n          description:\n            'Local project directory, readable from the machine running the DevKit MCP server (copy to the local temp dir first if not).',\n        },\n        remote_dir: {\n          type: 'string',\n          description:\n            'Remote parent directory where project will be extracted (default: /workspace). Final layout: <remote_dir>/<dirname>/',\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        exclude: {\n          type: 'array',\n          items: { type: 'string' },\n          description: 'Patterns to exclude from archive (default: .git, node_modules, __pycache__, .venv)',\n        },\n        extract: {\n          type: 'boolean',\n          description: 'Extract tar.gz on sandbox after upload (default: true)',\n        },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 300000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_deploy_nginx',\n    description:\n      'Deploy an nginx configuration on the sandbox and reload. Takes nginxType, port, project, outputDir from framework detection and writes the correct template (SPA try_files, SSR reverse proxy, or static). Also fixes directory traverse permissions on the project path. Use this instead of manually constructing nginx config — it handles permissions, template selection, and reload in one call. If the requested port is already in use, the actual port is auto-incremented and returned in \"port\" alongside a warning.',\n    inputSchema: {\n      type: 'object',\n      required: ['nginx_type', 'port', 'project', 'output_dir'],\n      properties: {\n        nginx_type: {\n          type: 'string',\n          description:\n            'Nginx config type from framework detection: spa (try_files fallback for SPA/SSG/cross-platform), proxy (reverse proxy for SSR), or static (plain root for Hugo/Hexo).',\n          enum: ['spa', 'proxy', 'static'],\n        },\n        port: { type: 'number', description: 'Listen port (from framework detection).' },\n        project: { type: 'string', description: 'Project directory name under /workspace, e.g. movie-ticket.' },\n        output_dir: {\n          type: 'string',\n          description: 'Build output directory relative to /workspace/<project>, e.g. dist/build/h5.',\n        },\n        node_port: { type: 'number', description: 'Node.js app port for SSR (required when nginx_type=proxy).' },\n        public_port: { type: 'number', description: 'Public listen port for SSR proxy (optional, defaults to port).' },\n        config_name: {\n          type: 'string',\n          description:\n            'Config file name (without .conf suffix). Defaults to the project name, ensuring each project gets its own config. Override with distinct names (e.g. admin, docs) for sub-app deployments.',\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 30000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_deploy_check',\n    description:\n      'Run a deployment completeness check on the sandbox. Verifies nginx is serving, output directory exists, DevBridge tunnel is active and accessible, and QR code exists (cross-platform). Returns a score, nextStep, and (when the DevBridge tunnel is missing) an executable \"remediation\" command string. Call this at the end of a deployment workflow to confirm everything is working before reporting success.',\n    inputSchema: {\n      type: 'object',\n      required: ['port', 'project', 'output_dir'],\n      properties: {\n        port: { type: 'number', description: 'App listen port (from framework detection).' },\n        project: { type: 'string', description: 'Project directory name under /workspace.' },\n        output_dir: {\n          type: 'string',\n          description: 'Build output directory relative to /workspace/<project>, e.g. dist/build/h5.',\n        },\n        framework_type: {\n          type: 'string',\n          description: 'Framework type from detect_framework. Set to cross-platform for QR code check.',\n          enum: ['spa', 'ssr', 'ssg', 'cross-platform', 'monorepo', 'static'],\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 30000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_expose_tunnel',\n    description:\n      'Expose a port on the sandbox to a public DevBridge tunnel URL (devbridge 0.2.x). Authenticates automatically (probing AK/SK vs API-Key builds, using /tmp/hw_creds.sh and /tmp/hw_api_key as injected by huaweicloud_sandbox_credentials), pre-cleans stale tunnels to avoid quota errors, starts the host, extracts the public URL (https://<id>-<port>.devbridge-s2.hwtunnel.com), and health-checks it before returning. AUTO-ENROLLS the tunnel into the keepalive watchdog (host re-attach + daily 720h renewal + health check) by default, merged into existing coverage — pass keepalive:false to opt out. Use the ACTUAL port reported by huaweicloud_sandbox_deploy_nginx (its \"port\" field auto-increments on conflict) — never the originally requested port. Returns ok, publicUrl, port, tunnelId, keepalive.enrolled, and warnings. If the API Key is missing on a release build it returns ok:false with instructions to create one.',\n    inputSchema: {\n      type: 'object',\n      required: ['port'],\n      properties: {\n        port: {\n          type: 'number',\n          description:\n            'Actual port nginx is listening on — use the \"port\" value returned by huaweicloud_sandbox_deploy_nginx, not the originally requested port.',\n        },\n        expiry_hours: {\n          type: 'number',\n          description:\n            'Tunnel lifetime in hours via devbridge -e (1-720; 720 = the 30-day maximum, default 72). The expiry is a rolling window — the keepalive watchdog renews daily to keep the URL alive indefinitely.',\n        },\n        keepalive: {\n          type: 'boolean',\n          description:\n            'Auto-enroll the tunnel into the keepalive watchdog (default true — every tunnel deployed to the sandbox must be keepalive-protected). Pass false only when the caller explicitly manages keepalive itself.',\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 90000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_renew_tunnel',\n    description:\n      'Renew a DevBridge tunnel lifetime via devbridge update <tunnelId> -e <hours> (1-720; 720 = the 30-day maximum). The expiry is a rolling window: renewal sets expiration = now + hours regardless of remaining time, so renewing before expiry keeps the SAME tunnel URL alive indefinitely. A renewal counts as ok only when the update succeeds AND show -v reports the absolute tunnelExpiration — the management plane can lose a tunnel record (10002 \"tunnel not found\") while the data plane keeps serving. Returns ok, tunnelId, expiresAt (ISO), renewedForHours. Pair with huaweicloud_sandbox_keepalive_watchdog for unattended daily renewal.',\n    inputSchema: {\n      type: 'object',\n      required: ['tunnel_id'],\n      properties: {\n        tunnel_id: {\n          type: 'string',\n          description:\n            'Short tunnel ID from huaweicloud_sandbox_expose_tunnel (e.g. nv2dvv6w) — extractable from the public URL as https://<tunnel_id>-<port>.devbridge-s2.hwtunnel.com.',\n        },\n        expiry_hours: {\n          type: 'number',\n          description:\n            'Renewal horizon in hours (1-720, default 720). The expiration becomes now + expiry_hours (rolling window).',\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 60000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_keepalive_watchdog',\n    description:\n      'Install a keepalive watchdog in the sandbox that keeps DevBridge tunnel URLs alive indefinitely (three-layer pattern, proven in the 2026-10 tunnel-persistence test): (1) re-attaches the host with devbridge host <tunnelId> if the process dies — the URL is bound to the tunnel ID so it never changes; (2) renews every tunnel daily with devbridge update <tunnelId> -e 720 (29-day failure tolerance); (3) health-checks each URL every 5 minutes, logging warnings to /tmp/tunnel-keepalive.log. Installs as a setsid-detached loop at /tmp/tunnel-keepalive.sh; re-running replaces the old loop. URLs are hardcoded per tunnel because devbridge port list output is wrapped in OSC escapes that break anchored greps. Call AFTER huaweicloud_sandbox_expose_tunnel; requires DevBridge credentials (auth) in the sandbox.',\n    inputSchema: {\n      type: 'object',\n      required: ['tunnels'],\n      properties: {\n        tunnels: {\n          type: 'array',\n          description:\n            'Tunnels to watch. Get tunnelId + url from huaweicloud_sandbox_expose_tunnel (publicUrl contains the tunnelId as https://<tunnel_id>-<port>.devbridge-s2.hwtunnel.com).',\n          items: {\n            type: 'object',\n            required: ['tunnel_id', 'url'],\n            properties: {\n              tunnel_id: { type: 'string', description: 'Short tunnel ID (e.g. kag7rozs).' },\n              url: { type: 'string', description: 'Full public https URL of the tunnel (used for the health check).' },\n            },\n          },\n        },\n        workspace_id: {\n          type: 'string',\n          description:\n            'Workspace ID from huaweicloud_sandbox_connect return value. Required - must be passed explicitly when HW_WORKSPACE_ID is not set.',\n        },\n        username: { type: 'string', description: 'Login username (default: root)' },\n        timeout_ms: { type: 'number', description: 'Execution timeout in milliseconds (default: 60000)' },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_check_user',\n    description:\n      'Check if the current user has completed real-name verification and signed the required agreements. Returns 200 {realnameVerified, agreementSigned} when all good; throws 403 HDKIT_NOT_REALNAME / HDKIT_NOT_AGREEMENT / HDKIT_NOT_REALNAME_AND_AGREEMENT to indicate what is missing. Never signs anything itself.',\n    inputSchema: {\n      type: 'object',\n      properties: {},\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_sign_agreement',\n    description:\n      \"Sign all unsigned or outdated agreements for the current user. Required before huaweicloud_sandbox_connect if check-user returns agreementSigned=false. CRITICAL: only call after the user explicitly consents to signing — never sign agreements on the user's behalf without their explicit request.\",\n    inputSchema: {\n      type: 'object',\n      properties: {},\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_connect',\n    description:\n      'Connect to a sandbox via hdkitservice. One user one instance - reuses existing sandbox if available, otherwise creates a new one. Returns session_id, dev_stage_id, connection_id, connection_address, and expiresAt (STS credential expiry).',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        source: {\n          type: 'string',\n          description:\n            'Source identifier (default: WEB). Options: VSCODE, CLI, WEB, WEBVNC, WEBPTY, WEBIDE, CURSOR, etc.',\n        },\n        template_id: { type: 'string', description: 'Template ID; overrides server default (only for new sandbox)' },\n        flavor_id: { type: 'string', description: 'Flavor ID; overrides server default (only for new sandbox)' },\n        env: { type: 'object', description: 'Environment variables to set in the sandbox (only for new sandbox)' },\n        git: {\n          type: 'object',\n          description: 'Git repo config (only for new sandbox)',\n          properties: {\n            repo_url: { type: 'string', description: 'Git repository URL' },\n            repo_branch: { type: 'string', description: 'Git branch' },\n            repo_name: { type: 'string', description: 'Repository name' },\n            target_path: { type: 'string', description: 'Clone target path in sandbox' },\n            open_type: { type: 'string', description: 'Open type' },\n          },\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_sandbox_credentials',\n    description:\n      'Configure temporary AK/SK for a sandbox via hdkitservice. Validates the current AK/SK against IAM before injecting (invalid SK is rejected here instead of failing later with APIGW.0301 during exec), then injects temporary credentials into the sandbox. Also injects an optional DevBridge API Key — required for devbridge 0.2.x tunnel exposure because 0.2.x removed AK/SK login. The API Key is a long-lived account-level credential, so it is stored in a separate file (/tmp/hw_api_key, 0600) from the temporary AK/SK (/tmp/hw_creds.sh). Source of truth: local HW_API_KEY env first, then the api_key param. The sandbox