{\n    name: 'huaweicloud_competition_voucher_claim',\n    description:\n      '领取华为开发者大赛·小红书skill创新赛专属华为云代金券。前置条件：用户已完成该赛事报名（后端自动校验，未报名返回 code=HDKIT_NOT_SIGNED_UP）。仅当用户明确要求领取该赛事代金券时调用，不要主动提示。重复领取会返回已领取。',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        domain_id: {\n          type: 'string',\n          description: 'Optional. Leave empty in production — account is resolved from IAM automatically.',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_check_update',\n    description:\n      '检查 huaweicloud-devkit 插件是否有新版本。结果含 currentVersion / latestStable / latestNext / targetVersion / updateAvailable / dismissExpiresAt / result。支持 dismiss:true 记录用户拒绝（3 天冷却，新版本会重新提醒）。',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        dismiss: { type: 'boolean', description: '用户拒绝升级时传 true，记录冷却状态。' },\n        dismissVersion: {\n          type: 'string',\n          description: '与 dismiss:true 搭配，用户拒绝的版本号。缺省时用当前检测到的 targetVersion。',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_upgrade',\n    description:\n      '升级 huaweicloud-devkit 到最新版本。执行前必须先征得用户同意。version 仅支持 \"latest\"。完成后需重启会话生效。',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        version: { type: 'string', description: '仅支持 \"latest\"（默认）。' },\n        target: {\n          type: 'string',\n          description: 'agent 目标（opencode/codex/codearts/.../all）。缺省时用 all（仅更新已安装的）。',\n        },\n      },\n    },\n  },\n  {\n    name: 'huaweicloud_obs_set_website_config',\n    description:\n      '配置 OBS 桶的静态网站托管。KooCLI OBS 不支持 SetBucketWebsite API，此工具内部实现 AWS4 签名调用 OBS REST API，屏蔽签名细节。支持 set（配置）、get（查询）、delete（删除）三种操作。操作前需确保桶已创建且已设置 public-read ACL。',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        action: {\n          type: 'string',\n          enum: ['set', 'get', 'delete'],\n          description: '操作类型：set=配置静态网站托管，get=查询当前配置，delete=删除配置',\n        },\n        bucket: { type: 'string', description: 'OBS 桶名称' },\n        region: { type: 'string', description: 'OBS 桶所在区域，如 cn-north-4' },\n        indexDocument: {\n          type: 'string',\n          description: '首页文件名（action=set 时必填），如 index.html',\n        },\n        errorDocument: {\n          type: 'string',\n          description: '错误页面文件名（action=set 时可选），如 404.html 或 error.html',\n        },\n      },\n      required: ['action', 'bucket', 'region'],\n    },\n  },\n  {\n    name: 'huaweicloud_obs_set_cors',\n    description:\n      '配置 OBS 桶的 CORS 规则（浏览器直传前置条件）。KooCLI OBS 不支持 cors 子命令，此工具内部实现 AWS4 签名调用 OBS REST API（PUT/GET/DELETE /?cors），屏蔽签名细节。支持 set（配置）、get（查询）、delete（删除）三种操作。allowedMethod 必须含 HEAD（BrowserJS SDK 每次操作前发 HEAD ?apiversion 探测，缺 HEAD 时浏览器吞掉探测请求）。配置成功后用返回体中的 verify 命令做 OPTIONS 预检验证（200 + Access-Control-Allow-Origin 才算成功）。',\n    inputSchema: {\n      type: 'object',\n      properties: {\n        action: {\n          type: 'string',\n          enum: ['set', 'get', 'delete'],\n          description: '操作类型：set=配置 CORS 规则，get=查询当前规则，delete=删除规则',\n        },\n        bucket: { type: 'string', description: 'OBS 桶名称' },\n        region: { type: 'string', description: 'OBS 桶所在区域，如 cn-north-4' },\n        rules: {\n          type: 'array',\n          description:\n            'CORS 规则数组（action=set 时必填）。每条规则：allowedOrigin（如 https://your-app）、allowedMethod 数组（GET/PUT/POST/DELETE/HEAD，必须含 HEAD）、allowedHeader 数组（默认 [\"*\"]）、maxAgeSeconds（默认 3000）',\n          items: {\n            type: 'object',\n            properties: {\n              allowedOrigin: { type: 'string', description: '允许的来源，如 https://your-app.example.com 或 *' },\n              allowedMethod: {\n                type: 'array',\n                items: { type: 'string' },\n                description: '允许的 HTTP 方法，必须包含 HEAD',\n              },\n              allowedHeader: {\n                type: 'array',\n                items: { type: 'string' },\n                description: '允许的请求头，默认 [\"*\"]',\n              },\n              maxAgeSeconds: { type: 'number', description: '预检结果缓存秒数，默认 3000' },\n            },\n            required: ['allowedOrigin', 'allowedMethod'],\n          },\n        },\n      },\n      required: ['action', 'bucket', 'region'],\n    },\n  },\n];\n\nfunction toolInvokeValue(name, args) {\n  if (name === 'huaweicloud_run_readonly_command' || name === 'huaweicloud_run_approved_command') {\n    const cmdArgs = args.args || [];\n    const filtered = cmdArgs.filter((a) => !a.startsWith('--') && !a.startsWith('-') && !a.includes('='));\n    if (filtered.length >= 2) return `hcloud ${filtered.slice(0, 2).join(' ')}`;\n  }\n  if (name === 'huaweicloud_list_operations' && args.service) {\n    return args.service;\n  }\n  if (name === 'huaweicloud_retrieve_skill' && args.name) {\n    return args.name;\n  }\n  if (name === 'huaweicloud_hook_check_command' && args.command) {\n    const parts = args.command.split(/\\s+/).filter((p) => !p.startsWith('--'));\n    if (parts[0] === 'hcloud' && parts[1]) return `hcloud ${parts.slice(1, 3).join(' ')}`;\n    return parts.slice(0, 2).join(' ');\n  }\n  return '1';\n}\n\nconst execFilePromise = promisify(execFile);\n\nasync function isGitAvailable() {\n  try {\n    await execFilePromise('git', ['--version'], { timeout: 5000 });\n    return true;\n  } catch {\n    return false;\n  }\n}\n\nasync function gitCloneToLocal(repoUrl, branch, targetBasename) {\n  const tempRoot = join(tmpdir(), `hw-sandbox-git-${Date.now()}`);\n  const cloneDir = join(tempRoot, targetBasename);\n  mkdirSync(tempRoot, { recursive: true });\n  const args = ['clone', '--depth', '1'];\n  if (branch) args.push('-b', branch);\n  args.push(repoUrl, cloneDir);\n  await execFilePromise('git', args, { timeout: 120000 });\n  return { cloneDir, tempRoot };\n}\n\nasync function transferGitRepo(args, devStageId, connectResult) {\n  const git = args.git;\n  if (!git?.repo_url || !git?.target_path) return;\n\n  const { repo_url, repo_branch, target_path } = git;\n\n  try {\n    const existsCheck = await execOneShot(\n      devStageId,\n      `test -d \"${target_path}/.git\" && echo \"EXISTS\" || echo \"NOT_EXISTS\"`,\n      'root',\n      10000,\n    );\n    if (String(existsCheck.stdout || '').includes('EXISTS')) {\n      connectResult._repoStatus = 'already_exists';\n      return;\n    }\n  } catch {\n    /* 检查失败继续 */\n  }\n\n  const hasGit = await isGitAvailable();\n  if (hasGit) {\n    let tempRoot = null;\n    try {\n      const targetName = basename(target_path);\n      const { cloneDir, tempRoot: root } = await gitCloneToLocal(repo_url, repo_branch, targetName);\n      tempRoot = root;\n      await uploadProjectWithSession(devStageId, cloneDir, dirname(target_path), 'root', 300000, {\n        extract: true,\n        exclude: ['.git', 'node_modules'],\n      });\n      connectResult._repoStatus = 'uploaded_from_local';\n      return;\n    } catch {\n      /* 本地方式失败，进入兜底 */\n    } finally {\n      if (tempRoot) {\n        try {\n          rmSync(tempRoot, { recursive: true, force: true });\n        } catch {\n          /* 清理失败忽略 */\n        }\n      }\n    }\n  }\n\n  const branchFlag = repo_branch ? `-b ${repo_branch}` : '';\n  await execOneShot(\n    devStageId,\n    `mkdir -p $(dirname \"${target_path}\") && git clone --depth 1 ${branchFlag} \"${repo_url}\" \"${target_path}\"`,\n    'root',\n    120000,\n  );\n  connectResult._repoStatus = 'cloned_in_sandbox';\n}\n\nconst pendingConfirms = new Map();\n// Tombstones for confirm tokens already consumed, so a repeat\n// huaweicloud_auth_confirm call can be classified as already_processed\n// instead of not_found (D4-24, #745). Kept in-memory only: confirm tokens\n// are session-scoped and never persisted across processes.\nconst consumedConfirms = new Map();\n\nfunction readImportFile() {\n  const path = join(dirname(globalCredentialsPath()), 'creds-import.json');\n  try {\n    if (!existsSync(path)) return null;\n    const data = JSON.parse(readFileSync(path, 'utf8'));\n    return {\n      ak: St